.catalog-sidebar {
    background: #f8f9fa;
    padding: 1.5rem;
    border-radius: 8px;
    border: 1px solid #e0e0e0;
}

.catalog-sidebar h4 {
    margin: 0 0 1rem;
    font-size: 1.2rem;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h5 {
    margin: 0 0 0.5rem;
    font-size: 0.95rem;
    color: #495057;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.25rem 0;
    cursor: pointer;
    font-size: 0.9rem;
}

.price-inputs {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.price-inputs input {
    width: 80px;
    padding: 0.4rem 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.9rem;
}

.price-inputs span {
    color: #6c757d;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 1rem;
}

.btn-apply {
    padding: 0.5rem 1rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 500;
}

.btn-apply:hover {
    background: #0b5ed7;
}

.btn-clear {
    padding: 0.5rem 1rem;
    background: transparent;
    color: #6c757d;
    border: 1px solid #6c757d;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 500;
}

.btn-clear:hover {
    background: #6c757d;
    color: #fff;
}

